c6ae2ae5-1f87-44ce-9faf-743f4f841619	public class ForTheSecond {\n\n    Node head;\n\n    private static class Node {\n        String data;\n        Node next;\n\n        Node(String data) {\n            this.data = data;\n            this.next = null;\n        }\n    }\n\n    public void insert(String data) {\n        Node sll = new Node(data);\n        if (head == null) {\n            head = sll;\n        } else {\n            Node current = head;\n            while (current.next != null) {\n                current = current.next;\n            }\n            current.next = sll;\n        }\n    }\n\n    public void display() {\n        Node current = head;\n        int index = 0; // Added index variable\n        while (current != null) {\n            System.out.print("(" + index + ")" + current.data + " --> ");\n            current = current.next;\n            index++;\n        }\n        System.out.println("null");\n    }\n\n    public int size() {\n        int count = 0;\n        Node current = head;\n        while (current != null) {\n            count++;\n            current = current.next;\n        }\n        return count;\n    }\n\n    public SearchResult find(String searchKey) {\n        Node current = head;\n        int index = 0;\n\n        while (current != null) {\n            if (current.data.equals(searchKey)) {\n                return new SearchResult(true, index); // Return index when found\n            }\n            current = current.next;\n            index++;\n        }\n\n        return new SearchResult(false, -1); // Return -1 if not found\n    }\n\n    public Node reverse() {\n        if (head == null) {\n            return null;\n        }\n        Node current = head;\n        Node previous = null;\n        Node next = null;\n        while (current != null) {\n            next = current.next;\n            current.next = previous;\n            previous = current;\n            current = next;\n        }\n        // Return the new head of the reversed list\n        return previous;\n    }\n\n    public static void main(String[] args) {\n        ForTheSecond dll = new ForTheSecond();\n        dll.insert("Mobile");\n        dll.insert("Samsung s23");\n        dll.insert("Samsung s22");\n        dll.insert("Samsung s21fe");\n        dll.insert("Google pixe 7");\n        dll.insert("Samsung z flip");\n\n        dll.display();\n        int size = dll.size();\n        System.out.println("Size: " + size);\n\n        SearchResult result = dll.find("Samsung s21fe");\n        if (result.isFound()) {\n            System.out.println("Search key found at index: " + result.getIndex());\n            \n            // Calculate the index in the reversed list\n            int reversedIndex = size - result.getIndex() - 1;\n            System.out.println("Index in reversed list: " + reversedIndex);\n        } else {\n            System.out.println("Search key not found!!!");\n        }\n\n        Node reversedHead = dll.reverse();\n\n        System.out.println("\\nReversed list:");\n        // Display the reversed list\n        while (reversedHead != null) {\n            System.out.print(reversedHead.data + "-->");\n            reversedHead = reversedHead.next;\n        }\n        System.out.println("null");\n    }\n\n    private static class SearchResult {\n        private final boolean found;\n        private final int index;\n\n        public SearchResult(boolean found, int index) {\n            this.found = found;\n            this.index = index;\n        }\n\n        public boolean isFound() {\n            return found;\n        }\n\n        public int getIndex() {\n            return index;\n        }\n    }\n}\ninsert "Lenevo"at position in this code  after Samsung s21fe	2023-12-21 20:31:25.171329	f	\N	0	99b3a89c-4f6b-41a0-a4ff-a829db36acce	48122ec5-5f65-4588-a012-0c7bfe15802f	\N	2023-12-21 20:31:25.171419
